/**
 * The FlowCode feature catalog: one structured, categorised description of everything in the app — pages, sections,
 * components, actions, settings and concepts — with what each does, how to use it, where it lives and what it relates
 * to. It is the Copilot's ground truth ("Explain this feature" and questions about the app retrieve from it).
 *
 * Keep entries factual and current: when a feature is added, moved or renamed, update its entry here.
 */
export type FeatureKind = "page" | "section" | "component" | "action" | "setting" | "concept";

export interface Feature {
  id: string;
  kind: FeatureKind;
  /** Top-level area, for grouping: Navigation, Dashboard, Builder, My Projects, FlowReport, Knowledge Hub, Research, Network, Prompts & Skills, Agents, System, System Settings, Copilot, How builds work. */
  area: string;
  title: string;
  /** Route pattern. ":project" = a project id, "*" = every page. */
  route?: string;
  /** Parent feature id (a section's page, a tab's panel…). */
  parent?: string;
  /** One sentence: what it is. */
  summary: string;
  /** What it does and why it matters, in plain words. */
  details?: string;
  /** Short steps for using it. */
  howTo?: string[];
  /** Its parts, when they are not catalog entries of their own (sub-entries via `parent` are used otherwise). */
  parts?: Array<{ name: string; what: string }>;
  /** Related feature ids. */
  related?: string[];
  /** UI anchors (data-guide ids from APP_GUIDE) where it lives. */
  anchors?: string[];
  /** A tab to open on its page so it is visible (the tab's id, i.e. its data-tab attribute). */
  tab?: string;
  keywords: string[];
  /** The on-screen control Show me points at (its data-cp), when it has no APP_GUIDE anchor. */
  cp?: string;
  /** For parts that only show in some situations: when (completes "It appears …"). Show me says so instead of stopping. */
  appearsWhen?: string;
  /** A window event Show me fires first to reveal it (e.g. "fc:show-overview" for parts of the builder's Overview). */
  reveal?: string;
  /** When it was added (YYYY-MM-DD): the Feature guide marks it New for NEW_FOR_DAYS days. */
  added?: string;
}

/** How long a feature counts as new in the Feature guide. */
export const NEW_FOR_DAYS = 30;
export function isNewFeature(f: Pick<Feature, "added">, now = Date.now()): boolean {
  if (!f.added) return false;
  const t = Date.parse(`${f.added}T00:00:00`);
  return Number.isFinite(t) && now - t < NEW_FOR_DAYS * 86_400_000 && now >= t;
}

