const words = (s: string) => new Set(s.toLowerCase().match(/[a-z0-9&]{3,}/g) ?? []);

/** Features that live on a route (exact page or its sub-pages). */
export function featuresForRoute(route: string): Feature[] {
  const clean = route.split("?")[0].replace(/\/prj_[\w]+/, "/:project");
  return FEATURE_CATALOG.filter((f) => f.route && f.route !== "*" && (clean === f.route || clean.startsWith(`${f.route}/`) || f.route.startsWith(`${clean}/`) || (f.route === "/" && clean === "/")));
}

/** Best-matching features for a question (title, summary and keywords). */
export function searchFeatures(query: string, max = 6): Feature[] {
  const q = words(query);
  if (!q.size) return [];
  return FEATURE_CATALOG.map((f) => {
    const kw = new Set(f.keywords.flatMap((k) => [...words(k)]));
    const text = words(`${f.title} ${f.summary}`);
    let score = 0;
    for (const w of q) score += (kw.has(w) ? 3 : 0) + (text.has(w) ? 1 : 0);
    return { f, score };
  })
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, max)
    .map((x) => x.f);
}

/** A feature, the features under it, and the ones it links to: everything needed to explain it fully. */
export function featureFamily(id: string): Feature[] {
  const root = FEATURE_CATALOG.find((f) => f.id === id || f.anchors?.includes(id));
  if (!root) return [];
  const children = FEATURE_CATALOG.filter((f) => f.parent === root.id);
  const related = (root.related ?? []).map((r) => FEATURE_CATALOG.find((f) => f.id === r)).filter((f): f is Feature => !!f);
  return [root, ...children, ...related.filter((r) => !children.includes(r))];
}

export function renderFeature(f: Feature): string {
  return [`## ${f.title} (${f.kind}, ${f.area})${f.route ? ` — ${f.route}` : ""}`, f.summary, f.details ?? "", f.howTo?.length ? `How to use: ${f.howTo.join(" ")}` : ""].filter(Boolean).join("\n");
}

/** The parts list and how-to steps for an explanation, straight from the catalog (no model involved). */
export function explainParts(id: string): { feature?: Feature; parts: Array<{ name: string; what: string }>; howTo: string[] } {
  const feature = FEATURE_CATALOG.find((f) => f.id === id || f.anchors?.includes(id));
  if (!feature) return { parts: [], howTo: [] };
  const children = FEATURE_CATALOG.filter((f) => f.parent === feature.id);
  const parts = children.length ? children.map((c) => ({ name: c.title, what: c.summary })) : (feature.parts ?? []);
  return { feature, parts, howTo: feature.howTo ?? [] };
}

/** Finds a catalog feature by its id or by one of its UI anchors (older steps used anchor ids). */
export function findFeature(idOrAnchor: string): Feature | undefined {
  return FEATURE_CATALOG.find((f) => f.id === idOrAnchor) ?? FEATURE_CATALOG.find((f) => f.anchors?.includes(idOrAnchor));
}

/** Where a guided step should take the user: the page, a tab to open there, and the element to highlight. */
export function stepTarget(idOrAnchor: string, projectId?: string): { feature?: Feature; route?: string; tab?: string; anchor?: string; needsProject: boolean; missing?: string; reveal?: string } {
  const feature = findFeature(idOrAnchor);
  if (!feature) return { anchor: idOrAnchor, needsProject: false };
  const parent = feature.parent ? FEATURE_CATALOG.find((p) => p.id === feature.parent) : undefined;
  const raw = feature.route && feature.route !== "*" ? feature.route : undefined;
  const needsProject = !!raw?.includes(":project");
  const route = raw ? (needsProject ? (projectId ? raw.replace(":project", projectId) : undefined) : raw) : undefined;
  const anchor = feature.anchors?.[0] ?? feature.cp ?? (idOrAnchor !== feature.id ? idOrAnchor : undefined) ?? parent?.anchors?.[0];
  return { feature, route, tab: feature.tab, anchor, needsProject, ...(feature.reveal ? { reveal: feature.reveal } : {}), ...(feature.appearsWhen ? { missing: `${feature.title} isn't showing right now: it appears ${feature.appearsWhen}.` } : {}) };
}
